require __DIR__.'/config.php';require_admin();$id=(int)($_GET['id']??$_POST['id']??0);$stmt=db()->prepare("SELECT id,name,email,role,active FROM users WHERE id=?");$stmt->execute([$id]);$target=$stmt->fetch();if(!$target){http_response_code(404);exit('Kullanıcı bulunamadı.');}if($id===(int)$_SESSION['user']['id']){redirect('profile.php');}if(normalize_role((string)$target['role'])===ROLE_COMPANY_MANAGER){http_response_code(403);exit('Firma yöneticisi bu ekrandan düzenlenemez.');}$key='profile_'.$id;$p=db()->prepare('SELECT setting_value FROM settings WHERE setting_key=?');$p->execute([$key]);$profile=json_decode((string)$p->fetchColumn(),true)?:[];$profile=array_merge(['phone'=>'','organization'=>'','address'=>'','state'=>'','zip_code'=>'','country'=>'Türkiye','language'=>'Türkçe','timezone'=>'Europe/Istanbul','currency'=>'TRY','avatar'=>''],$profile);$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='profile'){$name=trim($_POST['name']??'');$email=trim(strtolower($_POST['email']??''));$active=isset($_POST['active'])?1:0;if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Geçerli ad ve e-posta girin.';else{$check=db()->prepare('SELECT id FROM users WHERE LOWER(email)=LOWER(?) AND id<>? LIMIT 1');$check->execute([$email,$id]);if($check->fetch())$error='Bu e-posta adresi başka bir kullanıcı tarafından kullanılıyor. Aynı e-posta ile ikinci kullanıcı olamaz.';else try{$update=db()->prepare("UPDATE users SET name=?,email=?,active=? WHERE id=? AND role IN ('User','secretary','audiometrist','accounting')");$update->execute([$name,$email,$active,$id]);foreach(['phone','organization','address','state','zip_code','country','language','timezone','currency'] as $field)$profile[$field]=trim($_POST[$field]??'');$driver=db()->getAttribute(PDO::ATTR_DRIVER_NAME);$sql=$driver==='mysql'?'INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)':'INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON CONFLICT(setting_key) DO UPDATE SET setting_value=excluded.setting_value';db()->prepare($sql)->execute([$key,json_encode($profile,JSON_UNESCAPED_UNICODE)]);$target['name']=$name;$target['email']=$email;$target['active']=$active;$message='Kullanıcı profili güncellendi.';}catch(PDOException $e){$error='Bu e-posta adresi başka bir kullanıcı tarafından kullanılıyor. Aynı e-posta ile ikinci kullanıcı olamaz.';}}}
 if($action==='password'){$password=$_POST['password']??'';$confirm=$_POST['password_confirm']??'';if(strlen($password)<6)$error='Şifre en az 6 karakter olmalıdır.';elseif($password!==$confirm)$error='Şifre ve şifre tekrarı aynı olmalıdır.';else{$update=db()->prepare("UPDATE users SET password_hash=? WHERE id=? AND role IN ('User','secretary','audiometrist','accounting')");$update->execute([password_hash($password,PASSWORD_DEFAULT),$id]);$message='Kullanıcının şifresi değiştirildi.';}}
}
