<h2>Şifre Değiştir</h2><form class="password-form" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="password"><label>Yeni şifre<input type="password" name="password" minlength="6" autocomplete="new-password" required></label><label>Yeni şifre tekrar<input type="password" name="password_confirm" minlength="6" autocomplete="new-password" required></label><button class="save-profile">Kaydet</button></form></section></main></body></html>
